(7397380, 1162849, 137576, '<td valign="top">5.2 and no comments sad times</td>', '5.2 and no comments sad times', '2015-08-14 08:14:24.000000', NULL, 0),
(7397525, 1162534, 25024, '<td valign="top">I do wish I could stop being allocated my own images for critique!!!<br/> <br/>If anyone stops by and feels the urge to critique this I would be eternally grateful, thank you in anticipation.</td>', 'I do wish I could stop being allocated my own images for critique!!! If anyone stops by and feels the urge to critique this I would be eternally grateful, thank you in anticipation.', '2015-08-15 15:46:32.000000', NULL, 0),
(7397531, 1162890, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An interesting image, the product of an enquiring mind<br/> <br/>Although your images are often very different from each other I am starting to recognise your uniqueness which separates them from so much other work on DPC. You are not afraid to experiment and whats more you are not afraid to share them which enables us all to benefit from some interesting experimental imagery. This is another interesting example where we are treated to some recognisably near focused aspects together with some wildly out of focus elements in a reversal of what would be expected from a less experimental approach.<br/> <br/>I don''t regard this as anywhere near your best work but nevertheless it is no less interesting for the end result in helping us look at a scene in a very different way and at least one other person appreciates it too! Thanks Don, Sid</td>', '*Hello from Sid and the Critique Club* An interesting image, the product of an enquiring mind Although your images are often very different from each other I am starting to recognise your uniqueness which separates them from so much other work on DPC. You are not afraid to experiment and whats more you are not afraid to share them which enables us all to benefit from some interesting experimental imagery. This is another interesting example where we are treated to some recognisably near focused aspects together with some wildly out of focus elements in a reversal of what would be expected from a less experimental approach. I don''t regard this as anywhere near your best work but nevertheless it is no less interesting for the end result in helping us look at a scene in a very different way and at least one other person appreciates it too! Thanks Don, Sid', '2015-08-15 15:59:18.000000', NULL, 0),
(7398112, 1162829, 173303, '<td valign="top">loves this shot!<br/></td>', 'loves this shot!', '2015-08-17 21:28:50.000000', NULL, 0),
